mapper.select:
SELECT ABR_SN
  FROM ABUSE_REPORT
 WHERE RPRT_USR_SN = #{reporterUserSn}
   AND ABR_REF_TYPE_CD = #{referenceTypeCode}
   AND ABR_REF_SN = #{referenceSn}
 LIMIT 1

SELECT ABR_SN AS reportSn, ABR_REF_SN AS referenceSn, ABR_STATUS_CD AS statusCode FROM ABUSE_REPORT WHERE RPRT_USR_SN IS NOT NULL AND ABR_REF_TYPE_CD = #{referenceTypeCode} AND ABR_STATUS_CD IN (#{receivedStatusCode}, #{processingStatusCode}) AND ABR_REF_SN IN
#{referenceSn}
ORDER BY ABR_SN DESC

SELECT

  FROM ABUSE_REPORT ar
  LEFT JOIN CMM_CODE rt ON rt.CMM_CD = ar.ABR_TYPE_CD
  LEFT JOIN CMM_CODE st ON st.CMM_CD = ar.ABR_STATUS_CD
 WHERE ar.RPRT_USR_SN = #{reporterUserSn}
   AND ar.RSK_EVT_SN IS NULL


       AND ar.ABR_STATUS_CD IN ('ABSC0003', 'ABSC0004')


       AND ar.ABR_STATUS_CD = #{statusCode}


 ORDER BY ar.ABR_SN DESC
 LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM ABUSE_REPORT
 WHERE RPRT_USR_SN = #{reporterUserSn}
   AND RSK_EVT_SN IS NULL


       AND ABR_STATUS_CD IN ('ABSC0003', 'ABSC0004')


       AND ABR_STATUS_CD = #{statusCode}

SELECT ABR_SN
  FROM ABUSE_REPORT
 WHERE RPRT_USR_SN = #{reporterUserSn}
   AND RPTD_USR_SN <=> #{reportedUserSn}
   AND ABR_TYPE_CD = #{reportTypeCode}
   AND ABR_REF_TYPE_CD <=> #{referenceTypeCode}
   AND ABR_REF_SN <=> #{referenceSn}
   AND ABR_STATUS_CD IN (#{receivedStatusCode}, #{processingStatusCode})
 ORDER BY ABR_SN DESC
 LIMIT 1

SELECT COUNT(*)
  FROM ABUSE_REPORT_FILE rf
  JOIN FILES f ON f.FL_SN = rf.FL_SN
 WHERE rf.ABR_SN = #{reportSn}
   AND rf.FL_SN = #{fileSn}
   AND f.FL_USE_YN = 'Y'

SELECT EXISTS (
    SELECT 1
      FROM ABUSE_REPORT_TRADE
     WHERE ABR_SN = #{reportSn}
)

SELECT
FROM ABUSE_REPORT ar
ORDER BY CASE ar.ABR_STATUS_CD WHEN 'ABSC0001' THEN 0 WHEN 'ABSC0002' THEN 1 WHEN 'ABSC0003' THEN 2 WHEN 'ABSC0004' THEN 3 ELSE 4 END ASC, ar.ABR_REG_DT DESC, ar.ABR_SN DESC LIMIT #{size} OFFSET #{offset}

SELECT

FROM ABUSE_REPORT ar

WHERE ar.ABR_SN = #{reportSn}

SELECT

FROM ABUSE_REPORT ar

WHERE ar.RPTD_USR_SN = #{reportedUserSn}
ORDER BY ar.ABR_REG_DT DESC, ar.ABR_SN DESC
LIMIT #{limit}

SELECT EXISTS (
    SELECT 1
    FROM ABUSE_REPORT
    WHERE RPTD_USR_SN = #{reportedUserSn}
      AND ABR_STATUS_CD IN (#{receivedStatus}, #{processingStatus})
)
